from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()  # Set of all book IDs in the library
        # Dictionary mapping book_id to (user, borrow_date, due_date, is_returned)
        self.borrowed_books = {}
        # Dictionary mapping user to list of (book_id, borrow_date, return_date, fine)
        self.user_history = {}
        # Dictionary mapping user to current unpaid fines
        self.unpaid_fines_dict = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} not in library")

        # Check if user already has an unpaid book (user can hold at most one book at a time)
        if user in self.user_history:
            # Check if user has any currently borrowed book (not returned yet)
            for record in self.user_history[user]:
                if record[2] is None:  # return_date is None means still borrowed
                    raise ValueError(f"User {user} already has a borrowed book")

        # Calculate due date (borrow day + loan_days, skipping weekends)
        due_date = self._calculate_due_date(day, self.loan_days)

        # Record the borrowing
        if user not in self.user_history:
            self.user_history[user] = []
        self.user_history[user].append((book_id, day, None, 0.0))

        # Track in borrowed_books dictionary
        self.borrowed_books[book_id] = (user, day, due_date, False)

    def _calculate_due_date(self, start_date: date, days: int) -> date:
        """Calculate due date by adding 'days' business days (skipping weekends)"""
        current_date = start_date
        days_added = 0

        while days_added < days:
            current_date += timedelta(days=1)
            # Skip weekends (Saturday=5, Sunday=6)
            if current_date.weekday() < 5:  # Monday=0, Friday=4
                days_added += 1

        return current_date

    def _count_business_days(self, start_date: date, end_date: date) -> int:
        """Count business days (Monday-Friday) between start_date (exclusive) and end_date (inclusive)"""
        if start_date >= end_date:
            return 0

        count = 0
        current = start_date + timedelta(days=1)
        while current <= end_date:
            if current.weekday() < 5:  # Monday-Friday
                count += 1
            current += timedelta(days=1)
        return count

    def return_book(self, user: str, book_id: str, day: date) -> float:
        # Check if book exists and is borrowed by this user
        if book_id not in self.borrowed_books:
            raise ValueError(f"Book {book_id} not borrowed")

        borrower, borrow_date, due_date, is_returned = self.borrowed_books[book_id]
        if borrower != user:
            raise ValueError(f"Book {book_id} not borrowed by user {user}")

        # Find the borrowing record for this user
        record_found = False
        for i, record in enumerate(self.user_history.get(user, [])):
            if record[0] == book_id and record[2] is None:  # book_id matches and not returned yet
                # Calculate fine
                fine = 0.0
                if day > due_date:
                    # Count business days of delay (days after due_date up to and including return day)
                    delay_days = self._count_business_days(due_date, day)
                    fine = delay_days * self.daily_fine

                # Update the record with return date and fine
                self.user_history[user][i] = (book_id, borrow_date, day, fine)

                # Update borrowed_books to mark as returned
                self.borrowed_books[book_id] = (user, borrow_date, due_date, True)

                # Update unpaid fines
                if user not in self.unpaid_fines_dict:
                    self.unpaid_fines_dict[user] = 0.0
                self.unpaid_fines_dict[user] += fine

                record_found = True
                break

        if not record_found:
            raise ValueError(f"Book {book_id} not borrowed by user {user}")

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.unpaid_fines_dict.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.unpaid_fines_dict:
            self.unpaid_fines_dict[user] = 0.0
